"""Shared constants, labelling rule and the synthetic-data guard."""
from __future__ import annotations

import math

OUTCOME_DAYS = 7
MIN_OBSERVED_DAYS = 4
ADHERENCE_RATIO = 0.8
FEATURE_WINDOW_DAYS = 7          # days T-6 .. T inclusive
PURGE_GAP_DAYS = OUTCOME_DAYS + 1

SYNTHETIC = "synthetic"
REAL = "real"
SYNTHETIC_DISCLAIMER = (
    "SYNTHETIC DATA: generated by app.adherence.simulate under invented assumptions. "
    "Results demonstrate the pipeline only; they are NOT evidence about real users."
)


class SyntheticDataError(RuntimeError):
    pass


def require_synthetic_opt_in(data_origin: str, allow_synthetic: bool) -> None:
    if data_origin == SYNTHETIC and not allow_synthetic:
        raise SyntheticDataError(
            "Refusing to use synthetic data without allow_synthetic=True / --allow-synthetic.")


def _is_missing(v) -> bool:
    return v is None or (isinstance(v, float) and math.isnan(v))


def label_adherence(window_exercise, planned_daily_minutes):
    """Label one snapshot from its outcome window.

    `window_exercise` is the 7 daily exercise_minutes values for days T+1..T+7 with
    None/NaN for unlogged days. Returns (observed: bool, adhered: int | None).
    Unobserved snapshots (< MIN_OBSERVED_DAYS logged) get no label.
    """
    logged = [float(v) for v in window_exercise if not _is_missing(v)]
    if len(logged) < MIN_OBSERVED_DAYS:
        return False, None
    mean = sum(logged) / len(logged)
    return True, int(mean >= ADHERENCE_RATIO * planned_daily_minutes)
